<?php
namespace App\Http\Controllers;
use App\Models\Quiz;
use App\Models\QuizAttempt;
use Illuminate\Http\Request;
class QuizController extends Controller { public function index(Request $request){$programIds=$request->user()->enrollments()->pluck('program_id');$quizzes=Quiz::where('is_active',true)->whereIn('program_id',$programIds)->get();return view('quizzes.index',compact('quizzes'));} public function show(Request $request,Quiz $quiz){$this->allow($request,$quiz);$quiz->load('questions.options');return view('quizzes.show',compact('quiz'));} public function submit(Request $request,Quiz $quiz){$this->allow($request,$quiz);$quiz->load('questions.options');$answers=$request->input('answers',[]);$score=0;$max=0;foreach($quiz->questions as $q){$max+=(float)$q->points;$selected=(array)($answers[$q->id]??[]);$correct=$q->options->where('is_correct',true)->pluck('id')->map(fn($v)=>(string)$v)->sort()->values()->all();$given=collect($selected)->map(fn($v)=>(string)$v)->sort()->values()->all();if($given===$correct)$score+=(float)$q->points;}$percent=$max>0?round($score/$max*100,2):0;$attempt=QuizAttempt::create(['quiz_id'=>$quiz->id,'user_id'=>$request->user()->id,'score'=>$score,'percent'=>$percent,'passed'=>$percent>=$quiz->pass_percent,'answers'=>$answers,'started_at'=>now(),'finished_at'=>now(),'ip'=>$request->ip()]);return redirect()->route('quizzes.index')->with('success',($attempt->passed?'Тест пройден: ':'Тест не пройден: ').$percent.'%');} private function allow(Request $r,Quiz $q): void {abort_unless($r->user()->enrollments()->where('program_id',$q->program_id)->exists(),403);} }
